create extension if not exists "pgcrypto";
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'customer' check(role in('admin','customer')),created_at timestamptz not null default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,name text not null,slug text unique not null,description text,price numeric(14,2) not null default 0,stock integer not null default 0,image_url text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),auth_user_id uuid references auth.users(id) on delete set null,name text not null,email text,phone text,address text,created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,customer_id uuid references public.customers(id) on delete set null,status text not null default 'pending',subtotal numeric(14,2) not null default 0,shipping_fee numeric(14,2) not null default 0,total numeric(14,2) not null default 0,created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,quantity integer not null check(quantity>0),unit_price numeric(14,2) not null,subtotal numeric(14,2) not null);
create table if not exists public.articles(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,excerpt text,content text,cover_url text,status text not null default 'draft',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),title text not null,description text,icon text,sort_order integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.customers enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.articles enable row level security;alter table public.services enable row level security;
create policy "public categories" on public.categories for select using(true);create policy "public products" on public.products for select using(is_active=true);create policy "public articles" on public.articles for select using(status='published');create policy "public services" on public.services for select using(is_active=true);
create policy "admin profiles" on public.profiles for all using(public.is_admin()) with check(public.is_admin());create policy "admin categories" on public.categories for all using(public.is_admin()) with check(public.is_admin());create policy "admin products" on public.products for all using(public.is_admin()) with check(public.is_admin());create policy "admin customers" on public.customers for all using(public.is_admin()) with check(public.is_admin());create policy "admin orders" on public.orders for all using(public.is_admin()) with check(public.is_admin());create policy "admin order items" on public.order_items for all using(public.is_admin()) with check(public.is_admin());create policy "admin articles" on public.articles for all using(public.is_admin()) with check(public.is_admin());create policy "admin services" on public.services for all using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public) values('nerforit-media','nerforit-media',true) on conflict(id) do nothing;
create policy "public media read" on storage.objects for select using(bucket_id='nerforit-media');create policy "admin media insert" on storage.objects for insert with check(bucket_id='nerforit-media' and public.is_admin());create policy "admin media update" on storage.objects for update using(bucket_id='nerforit-media' and public.is_admin());create policy "admin media delete" on storage.objects for delete using(bucket_id='nerforit-media' and public.is_admin());
